import { getSelectorTimezoneList, type GetSelectorTimezoneListResponse } from '~/client';

export const useSelectorTimezoneList = defineQuery(() => {
  const { data, isLoading, error } = useQuery({
    key: ['selector-timezones-list'],
    query: (): Promise<GetSelectorTimezoneListResponse> => getSelectorTimezoneList({ composable: '$fetch' }),
  });

  return {
    timezones: computed(() => data.value?.items ?? []),
    isLoading,
    error,
  };
});
